#include "trmm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A and B with the same semantics as the original C init_array().
 *
 * C version:
 *
 *   *alpha = 1.5;
 *   for (i = 0; i < m; i++) {
 *     for (j = 0; j < i; j++) {
 *       A[i][j] = (DATA_TYPE)((i+j) % m)/m;
 *     }
 *     A[i][i] = 1.0;
 *     for (j = 0; j < n; j++) {
 *       B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
 *     }
 *   }
 *
 * Mapping to Halide Buffers:
 *   - A is declared in C as A[m][m] and accessed as A[i][j].
 *     We store it as Buffer A(width=m, height=m) and access as A(j, i).
 *   - B is declared in C as B[m][n] and accessed as B[i][j].
 *     We store it as Buffer B(width=n, height=m) and access as B(j, i).
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = static_cast<num_t>(1.5);

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // Make Expr versions of m and n for use inside Halide expressions.
    Expr m_expr = Expr(m);
    Expr n_expr = Expr(n);

    // A(i,j):
    //   For j < i:  ( (i + j) % m ) / m
    //   For j == i: 1.0
    //   For j > i:  0.0 (never used by the kernel, but we define it anyway)
    init_A(j, i) =
        select(j < i,
               cast<num_t>(((i + j) % m_expr)) / cast<num_t>(m_expr),
               select(j == i,
                      static_cast<num_t>(1.0),
                      static_cast<num_t>(0.0)));

    // B(i,j): ( (n + (i - j)) % n ) / n
    init_B(j, i) =
        cast<num_t>(((n_expr + (i - j)) % n_expr)) / cast<num_t>(n_expr);

    // Simple CPU-locality- and SIMD-friendly schedules for the initializers:
    Target target = get_host_target();
    Type num_type = type_of<num_t>();

    // Vector width chosen for the element type on this CPU.
    int vec_A = std::min(target.natural_vector_size(num_type), m);
    int vec_B = std::min(target.natural_vector_size(num_type), n);
    if (vec_A < 1) vec_A = 1;
    if (vec_B < 1) vec_B = 1;

    // Row-major traversal: i outer, j inner; vectorize across j and
    // parallelize across rows i. This matches the C loops closely and
    // gives good spatial locality in x (j).
    init_A
        .reorder(j, i)
        .vectorize(j, vec_A)
        .parallel(i);

    init_B
        .reorder(j, i)
        .vectorize(j, vec_B)
        .parallel(i);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;
    // Buffer layout: width = number of columns, height = number of rows
    // A: M x M  -> Buffer(m, m) accessed as A(j, i) == A[i][j] in C
    // B: M x N  -> Buffer(n, m) accessed as B(j, i) == B[i][j] in C
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Vars
    Var i("i"), j("j");

    // Reduction domain over k in [0, m)
    RDom k(0, m, "k");

    // Func representing the result B := alpha * A^T * B
    // Original kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Dependence analysis: every access to B[k][j] reads the *original*
    // B, never an updated value. So each (i,j) is independent and
    // the closed form is:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // We implement this as an explicit reduction update. We keep the full
    // reduction range k in [0..M-1] and mask off k <= i with a select;
    // this exactly matches the math above and avoids illegal
    // self-references.
    //
    // Mapping indices to Halide:
    //   A[k][i]  -> A_param(i, k)  (see init_array() comments)
    //   B[k][j]  -> B_param(j, k)
    //   B[i][j]  -> B_param(j, i)
    //
    // We store the final result in B_result(j, i) == B[i][j].
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr zero = cast<num_t>(0);

    // Base value: alpha * B[i][j]
    trmm(j, i) = alpha_expr * B_param(j, i);

    // Accumulate alpha * A[k][i] * B[k][j] for k > i
    trmm(j, i) += select(k > i,
                         alpha_expr * A_param(i, k) * B_param(j, k),
                         zero);

    // ----------------------------
    // Schedule for performance
    // ----------------------------
    Target target = get_host_target();
    Type num_type = type_of<num_t>();

    // Choose a SIMD width that fits the element type and the problem size.
    int vec = std::min(target.natural_vector_size(num_type), n);
    if (vec < 1) vec = 1;

    // We want:
    //   - i (rows) as the outer parallel dimension
    //   - j (cols) as the inner vectorized dimension
    //
    // This gives good spatial locality on B_param(j, *) and on the
    // output trmm(j, i), as x/column is contiguous in memory.
    trmm
        .reorder(j, i)   // j innermost, i outermost
        .vectorize(j, vec)
        .parallel(i);

    // For the reduction update, reorder so that j stays innermost and
    // is vectorized, k (reduction) sits just outside it, and i is outer.
    // The reduction itself remains purely local to each (i,j), so
    // parallelizing across i is safe.
    trmm
        .update()
        .reorder(j, k, i);

    // Compile the kernel to machine code for the host
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Remember: B_result(jj, ii) == B[ii][jj] in the original C code
                std::cerr << B_result(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
