int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;
    // Buffer layout: width = number of columns, height = number of rows
    // A: M x M  -> Buffer(m, m) accessed as A(j, i) == A[i][j] in C
    // B: M x N  -> Buffer(n, m) accessed as B(j, i) == B[i][j] in C
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Vars: j is the fast-varying (x) dimension, i is the slow (y) dimension.
    Var i("i"), j("j");

    // Reduction domain over k in [0, m)
    RDom k(0, m, "k");

    // Func representing the result B := alpha * A^T * B
    //
    // Original kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Here A is unit-lower-triangular (A[i][i] = 1, A[i][j] = 0 for j > i).
    // All reads of B[k][j] use the *original* B, so there are no in-place
    // dependences across rows. We can express the closed form as:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Using the structure of A, we can equivalently write:
    //
    //   B_out[i][j] = alpha * sum_{k = 0..M-1} A[k][i] * B_in[k][j]
    //
    // because:
    //   - A[k][i] = 0 for k < i,
    //   - A[i][i] = 1,
    // so the sum over k automatically contributes B_in[i][j] via the diagonal
    // term, and ignores k < i.
    //
    // Mapping to Halide coordinates (x = column, y = row):
    //   A[k][i]  -> A_param(i, k)  because A(x=j,y=i) == A[i][j] in C
    //   B[k][j]  -> B_param(j, k)  because B(x=j,y=i) == B[i][j] in C
    //   B_out[i][j] -> trmm(j, i)
    //
    // Final expression:
    //   trmm(j, i) = alpha * sum_{k} A_param(i, k) * B_param(j, k)
    //
    // This removes the data-dependent lower bound and branch from the inner
    // reduction, which is friendlier to vectorization and the optimizer.
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);

    trmm(j, i) = alpha_expr * sum(A_param(i, k) * B_param(j, k));

    // ------------------------------------------------------------------
    // Schedule
    // ------------------------------------------------------------------
    //
    // Memory layout:
    //   - First dimension (j) is contiguous in memory for all Buffers.
    //   - Second dimension (i or k) has a stride of 'width'.
    //
    // Scheduling strategy:
    //   - Tile the (i,j) space to improve cache locality.
    //   - Vectorize across j (contiguous in memory).
    //   - Parallelize across tiles in i (rows) to use many cores.
    //
    // The reduction over k is kept serial within each (i,j) to avoid
    // extra storage and keep the implementation simple, but the outer
    // parallelism and vectorization still give good performance.

    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Tile sizes tuned for a typical x64; small enough to fit in caches,
    // large enough to amortize loop overhead. j-tile is a multiple of
    // the natural vector width so that vectorization has a clean inner loop.
    const int tile_j = vec * 8;  // e.g. 8*4 = 32 lanes for float with AVX2
    const int tile_i = 32;       // moderate number of rows per tile

    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    trmm
        // Tile over (j, i): j is fast-varying, i is slow.
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Vectorize along contiguous j dimension within a tile.
